={{ JSON.stringify({
  model: $json.model,
  temperature: 0,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: `Ты распознаёшь бумажный наряд-заказ зуботехнической лаборатории HELIOS по фото. Верни ТОЛЬКО JSON без пояснений, строго по схеме:
{
 "order_number": {"value": "строка из цифр", "confidence": 0..1},
 "date": {"value": "ДД.ММ.ГГГГ", "confidence": 0..1},
 "clinic": {"value": "", "confidence": 0..1},
 "doctor": {"value": "Фамилия И. О. врача", "confidence": 0..1},
 "patient_initials": {"value": "только инициалы, например П.И.С.", "confidence": 0..1},
 "teeth": {"value": [номера зубов FDI числами], "confidence": 0..1},
 "work_type": {"value": "одно из: Коронка цирконий | Коронка E.max | Металлокерамика | Винир | Мост | Вкладка | Другое", "confidence": 0..1},
 "units": {"value": целое число, "confidence": 0..1},
 "shade": {"value": "код VITA, например A2, B1, BL2, 2M2", "confidence": 0..1},
 "due_date": {"value": "ДД.ММ.ГГГГ", "confidence": 0..1},
 "comment": {"value": "", "confidence": 0..1}
}
Правила:
- ПАЦИЕНТ: никогда не возвращай фамилию, имя или отчество целиком — только первые буквы с точками ("Петров И. С." → "П.И.С."). Это требование 152-ФЗ.
- Зубы: сверяй крестики в зубной формуле и строку "Зубы через запятую"; если они расходятся — снижай confidence.
- Вид работы: отмеченный крестиком чекбокс.
- confidence — твоя честная оценка, что значение прочитано верно. Если поле закрыто пятном, размыто или неразборчиво — value: null и confidence не выше 0.3. Не угадывай.
- Ничего не выдумывай и не добавляй полей.` },
    { role: 'user', content: [
      { type: 'text', text: 'Распознай наряд на фото.' },
      { type: 'image_url', image_url: { url: $json.dataUrl } }
    ] }
  ]
}) }}

parameters.jsCode:
const resp = $input.first().json;
const raw = String(resp.choices?.[0]?.message?.content ?? '');
let fields;
try {
  fields = JSON.parse(raw.replace(/^\s*```(?:json)?\s*/i, '').replace(/\s*```\s*$/, ''));
} catch (e) {
  throw new Error('Модель вернула не JSON: ' + raw.slice(0, 200));
}
return [{ json: { fields, model: resp.model, usage: resp.usage || {} } }];
